// Verifies: AC-1, AC-2, AC-3, AC-5 (see verification/SHOP-142/VERIFICATION_PLAN.md)
import { test, expect } from '@playwright/test';

async function applyCode(page, code) {
  await page.getByLabel('Discount code').fill(code);
  const response = page.waitForResponse('**/api/cart/discount');
  await page.getByRole('button', { name: 'Apply' }).click();
  await response;
}

test.beforeEach(async ({ page }) => {
  await page.goto('/');
  await expect(page.getByTestId('subtotal')).toHaveText('$120.00');
});

test('SHOP-142 AC-1 cart page has a labelled discount code field and an Apply button', async ({ page }) => {
  await expect(page.getByLabel('Discount code')).toBeVisible();
  await expect(page.getByRole('button', { name: 'Apply' })).toBeEnabled();
});

test('SHOP-142 AC-2 SAVE10 shows the discount and a $108.00 total; FLAT20 then replaces it ($100.00)', async ({ page }) => {
  await applyCode(page, 'SAVE10');
  await expect(page.getByTestId('discount')).toHaveText('−$12.00');
  await expect(page.getByTestId('total')).toHaveText('$108.00');

  await applyCode(page, 'FLAT20');
  await expect(page.getByTestId('discount')).toHaveText('−$20.00');
  await expect(page.getByTestId('total')).toHaveText('$100.00');
});

test('SHOP-142 AC-3 an unknown code shows an error and leaves the total at $120.00', async ({ page }) => {
  await applyCode(page, 'NOPE99');
  await expect(page.getByRole('alert')).toBeVisible();
  await expect(page.getByTestId('total')).toHaveText('$120.00');
});

test('SHOP-142 AC-5 on a phone the shopper applies SAVE10 and sees $108.00 without sideways scrolling', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'mobile', 'Phone check runs in the mobile project only');
  await applyCode(page, 'SAVE10');
  await expect(page.getByTestId('total')).toHaveText('$108.00');
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  expect(overflow).toBeLessThanOrEqual(0);
});
